mapper.select:
SELECT 
FROM author_kyc_profile

    status = #{status}
    AND author_id = #{authorId}

ORDER BY submitted_at DESC, id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM author_kyc_profile

    status = #{status}
    AND author_id = #{authorId}

mapper.update:
UPDATE author_kyc_profile
SET status = #{toStatus}, reviewed_at = CURRENT_TIMESTAMP(3), reviewed_by = #{reviewerId},
    rejection_reason = #{reason}
WHERE id = #{id} AND status = 'PENDING' AND submission_version = #{expectedVersion}

